import{_ as o,o as a,c as t,a2 as r}from"./chunks/framework.BjkiRu3Q.js";const g=JSON.parse('{"title":"Google Maps, δρομολόγηση και API αφίξεων","description":"","frontmatter":{},"headers":[],"relativePath":"el/integrations/maps-arrivals-setup.md","filePath":"el/integrations/maps-arrivals-setup.md"}'),l={name:"el/integrations/maps-arrivals-setup.md"};function s(d,e,i,c,p,_){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="google-maps-δρομολογηση-και-api-αφιξεων" tabindex="-1">Google Maps, δρομολόγηση και API αφίξεων <a class="header-anchor" href="#google-maps-δρομολογηση-και-api-αφιξεων" aria-label="Permalink to &quot;Google Maps, δρομολόγηση και API αφίξεων&quot;">​</a></h1><p>Έλεγχος πηγαίου κώδικα v0.7.26. Απενεργοποιημένα εξ ορισμού. Η τοπική γεωγραφική απεικόνιση είναι ανεξάρτητη από αδειοδοτημένο οδικό χάρτη.</p><h2 id="ρυθμιση-google-cloud" tabindex="-1">Ρύθμιση Google Cloud <a class="header-anchor" href="#ρυθμιση-google-cloud" aria-label="Permalink to &quot;Ρύθμιση Google Cloud&quot;">​</a></h2><ol><li>Δημιουργήστε ξεχωριστό έργο Google Cloud, εγκεκριμένη χρέωση και διαφορετικά κλειδιά ανά λειτουργία με περιορισμούς API και περιβάλλοντος.</li><li>Ενεργοποιήστε Maps JavaScript API και δημιουργήστε map ID για προαιρετικό χάρτη browser. Περιορίστε το κλειδί στα ακριβή εγκεκριμένα HTTPS origins. Μόνο μετά από έγκριση ρυθμίστε τις μεταβλητές build:</li></ol><table tabindex="0"><thead><tr><th>Μεταβλητή</th><th>Χρήση</th></tr></thead><tbody><tr><td><code>VITE_ENABLE_GOOGLE_FLEET_MAP</code></td><td>Διακόπτης χάρτη (προεπιλογή false)</td></tr><tr><td><code>VITE_GOOGLE_MAPS_BROWSER_KEY</code></td><td>Κλειδί browser με περιορισμούς ιστοτόπου και API</td></tr><tr><td><code>VITE_GOOGLE_MAPS_MAP_ID</code></td><td>Εγκεκριμένο map ID</td></tr></tbody></table><ol start="3"><li>Για αναζήτηση τοποθεσίας χειριστή ενεργοποιήστε Places API (New) και Geocoding API. Ρυθμίστε μόνο στον διακομιστή το <code>TBPLUS_GOOGLE_LOCATION_SERVER_KEY</code> με περιορισμούς IP και API. Το <code>TBPLUS_ENABLE_GOOGLE_LOCATION_LOOKUP</code> παραμένει false έως έγκριση. Η αρχική αναζήτηση αφορά Ελλάδα και δεν αποθηκεύει αυτόματα διευθύνσεις παρόχου ούτε αλλάζει ναύλους.</li><li>Για οδικές εκτιμήσεις ενεργοποιήστε Routes API και χωριστό <code>TBPLUS_GOOGLE_ROUTES_SERVER_KEY</code> με περιορισμούς IP και API. Το <code>TBPLUS_ENABLE_GOOGLE_ROUTES</code> παραμένει false έως έλεγχο. Οι εκτιμήσεις δεν εγγυώνται άφιξη ή τιμή. Ελέγχονται φρεσκάδα GPS και εξουσιοδότηση· τα σκέλη είναι ανεξάρτητα.</li><li>Ρυθμίστε ποσοστώσεις και ειδοποιήσεις χρέωσης (δεν αποτελούν σκληρό όριο κόστους). Ελέγξτε CSP, αναφορά παρόχου, όρους ΕΟΧ, ιδιωτικότητα, ανάκληση δικαιωμάτων, αποτυχίες, GPS και τοπική εναλλακτική. Τα όρια εφαρμογής δεν αντικαθιστούν τις ποσοστώσεις cloud.</li></ol><h2 id="πληροφοριες-αφιξεων" tabindex="-1">Πληροφορίες αφίξεων <a class="header-anchor" href="#πληροφοριες-αφιξεων" aria-label="Permalink to &quot;Πληροφορίες αφίξεων&quot;">​</a></h2><p>Η v0.7.26 υποστηρίζει μόνιμα στοιχεία μεταφορικών μέσων, χρονικά τεκμηριωμένες χειροκίνητες παρατηρήσεις, έλεγχο ειδοποιήσεων και ενημέρωση οδηγού. Εκκρεμούν αυτόματη εξωτερική παρακολούθηση πτήσεων/πλοίων, εργασίες παρασκηνίου, πλήρη όρια χρήσης και ενεργοποίηση αδειοδοτημένου χάρτη. Δεν τεκμηριώνονται εγκεκριμένα ονόματα κλειδιών ή ζωντανή διαδικασία. Ελέγξτε κάλυψη, άδειες, φρεσκάδα και κόστος πριν από μελλοντική υλοποίηση. Οι εκτιμήσεις δεν αλλάζουν αυτόματα παραλαβές ή ναύλους.</p><p>Επίσημες αναφορές πηγαίου κώδικα: <a href="https://developers.google.com/maps/api-security-best-practices" target="_blank" rel="noreferrer">Ασφάλεια κλειδιών Maps</a>, <a href="https://developers.google.com/maps/documentation/places/web-service/place-autocomplete" target="_blank" rel="noreferrer">Places</a>, <a href="https://developers.google.com/maps/documentation/geocoding/guides-v3/requests-geocoding" target="_blank" rel="noreferrer">Geocoding</a>, <a href="https://developers.google.com/maps/documentation/routes/compute_route_directions" target="_blank" rel="noreferrer">Routes</a>.</p>',9)])])}const P=o(l,[["render",s]]);export{g as __pageData,P as default};
